<?php $result = $_SESSION['track_result'] ?? null; unset($_SESSION['track_result']); ?>
<section class="page-hero"><div class="container"><p class="eyebrow"><span></span><?= e(tr('SUIVI DE DOSSIER', 'APPLICATION TRACKING')) ?></p><h1><?= e(tr('Où en est votre candidature ?', 'Where does your application stand?')) ?></h1><p><?= e(tr('Saisissez le numéro de dossier reçu après la soumission et l’e-mail ou le téléphone indiqué dans votre candidature.', 'Enter your application reference and the email or phone number used in your application.')) ?></p></div></section>
<section class="section section-paper"><div class="container track-shell"><form class="track-form" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="track_application"><label class="field"><?= e(tr('Numéro de dossier','Application reference')) ?><input name="reference" placeholder="SE-2026-000001" required></label><label class="field"><?= e(tr('E-mail ou téléphone du candidat','Applicant email or phone')) ?><input name="contact" required></label><button class="button button-green" type="submit"><?= e(tr('Consulter le statut','Check status')) ?> <i class="bi bi-arrow-right"></i></button></form>
<?php if (is_array($result)): ?><article class="track-result"><div class="track-result-head"><div><p class="eyebrow eyebrow-dark"><span></span><?= e(tr('DOSSIER', 'APPLICATION')) ?> <?= e($result['reference']) ?></p><h2><?= e($result['project_name']) ?></h2><p><?= e($result['first_name'] . ' ' . $result['last_name']) ?></p></div><span class="status-pill"><?= e(tr(status_labels()[$result['status']] ?? $result['status'], status_labels()[$result['status']] ?? $result['status'])) ?></span></div><div class="track-meta"><span><?= e(tr('Soumis le','Submitted')) ?> <?= e(date('d/m/Y', strtotime($result['created_at']))) ?></span><span><?= e(tr('Mis à jour le','Updated')) ?> <?= e(date('d/m/Y', strtotime($result['updated_at']))) ?></span></div><div class="timeline"><?php $timeline=[['received','Candidature reçue'],['verification','Vérification administrative'],['review','Étude du projet'],['approved','Décision'],['support','Accompagnement']]; $progressIndex=match($result['status']){'new','received'=>0,'verification','information'=>1,'review'=>2,'shortlisted','approved','rejected'=>3,'support','closed'=>4,default=>0}; foreach($timeline as $i=>$item): $isDone=$i<=$progressIndex; ?><div class="timeline-item <?= $isDone?'done':'' ?>"><span class="timeline-dot"><?= $isDone?'<i class="bi bi-check2"></i>':'' ?></span><span><?= e(tr($item[1],$item[1])) ?></span></div><?php endforeach; ?></div><p class="form-hint"><?= e(tr('Les notes internes de l’équipe ne sont pas affichées ici.', 'Internal team notes are not shown here.')) ?></p></article>
<?php elseif ($result === false): ?><div class="alert alert-error"><?= e(tr('Aucun dossier ne correspond à ces informations. Vérifiez le numéro de référence et le contact renseigné.', 'No application matched those details. Check the reference number and contact information.')) ?></div><?php endif; ?>
<p class="form-hint track-help"><?= e(tr('Besoin d’aide ? Contactez l’équipe par WhatsApp après avoir consulté votre dossier.', 'Need help? Contact the team on WhatsApp after checking your application.')) ?></p></div></section>
